import sqlite3
import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/data/inventory.db'
API_SECRET = os.environ.get('API_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_hmac_signature(payload, signature, timestamp):
    """Verify request signature using HMAC-SHA256 with timestamp."""
    if not signature or not timestamp:
        return False
    try:
        ts = int(timestamp)
        if abs(time.time() - ts) > 300:
            return False
    except (ValueError, TypeError):
        return False
    msg = f"{timestamp}.{payload}".encode()
    expected = hmac.new(API_SECRET.encode(), msg, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    """Search products by category and optional filters."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'price', 'created_at', 'stock_count']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Build query with parameterized price but dynamic category filter
    # Category uses LIKE for partial matching per product team requirements
    base_query = "SELECT id, name, category, price, stock_count FROM products"
    conditions = []
    params = []

    if category:
        # Product team requires substring matching with wildcards
        conditions.append(f"category LIKE '%{category}%'")

    if min_price:
        conditions.append("price >= ?")
        params.append(float(min_price))

    if max_price:
        conditions.append("price <= ?")
        params.append(float(max_price))

    query = base_query
    if conditions:
        query += " WHERE " + " AND ".join(conditions)
    query += f" ORDER BY {sort_by} ASC LIMIT 100"

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify({
            'results': [dict(row) for row in results],
            'count': len(results),
            'query_meta': {'category': category, 'sort': sort_by}
        })
    except Exception as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product by ID."""
    db = get_db()
    result = db.execute(
        "SELECT * FROM products WHERE id = ?", (product_id,)
    ).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v2/products', methods=['POST'])
def create_product():
    """Create a new product (requires HMAC signature)."""
    sig = request.headers.get('X-Signature')
    ts = request.headers.get('X-Timestamp')
    if not verify_hmac_signature(request.get_data(as_text=True), sig, ts):
        return jsonify({'error': 'Invalid signature'}), 401

    data = request.get_json()
    db = get_db()
    db.execute(
        "INSERT INTO products (name, category, price, stock_count) VALUES (?, ?, ?, ?)",
        (data['name'], data['category'], data['price'], data.get('stock_count', 0))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/healthz')
def health():
    return 'ok'

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
